function localPaymentPanel(){const d=currentData();d.localPaymentCoverage??=[];if(!d.localPaymentCoverage.length)d.localPaymentCoverage.push({id:'local-'+crypto.randomUUID(),country:'',currencies:'',methods:'',conditions:''});return section('Local payments in local currency',sel('localPaymentSupport','Can customers pay through local payment methods in their local currency?', [['unknown','Not confirmed'],['yes','Yes'],['review','Case-by-case'],['no','No']],true,'offer')+'<p class="hint">A payment acceptance country/currency is separate from the currency paid out to the merchant. Record each supported country with its actual currencies and payment methods; do not assume all currencies apply in every country.</p>'+`<div data-condition="offer|localPaymentSupport|yes|review">${d.localPaymentCoverage.map((r,i)=>`<div class="summary-card" data-local-payment="${r.id}"><div class="grid">${sel('localPaymentCoverage.'+i+'.country','Customer payment country',countries,true,'offer')}${input('localPaymentCoverage.'+i+'.currencies','Local payment currencies — ISO codes','text',true,'offer','For example BRL, MXN or THB; only currencies supported in this country.')}${input('localPaymentCoverage.'+i+'.methods','Local payment methods','text',true,'offer','Specify the supported methods for this country.')}${input('localPaymentCoverage.'+i+'.conditions','Restrictions / merchant eligibility conditions','text',false,'offer')}</div>${d.localPaymentCoverage.length>1?`<button type="button" data-remove-local="${r.id}">Remove country</button>`:''}</div>`).join('')}<button type="button" id="add-local-payment">Add another country</button></div>`);}
