h+=card('Supporting documents',7,state.documents.map(d=>[d.name,[d.kind,d.visibility,d.status].join(' · ')]));
h+=card('Partnership & benefits',7,[['Contact',[state.core.contactName,state.core.contactEmail,state.core.contactRole].filter(Boolean).join(' · ')],['Benefits',state.core.benefits],['Pipeline',state.core.pipeline]]);
